const SIGN_KEY = "b5efb1a93d2s52d1bf14dc0ccc1b1bb0";

async function hmacSha256(message: string, key: string): Promise<string> {
    const encoder = new TextEncoder();
    const cryptoKey = await crypto.subtle.importKey(
        "raw",
        encoder.encode(key),
        { name: "HMAC", hash: "SHA-256" },
        false,
        ["sign"],
    );
    const signature = await crypto.subtle.sign("HMAC", cryptoKey, encoder.encode(message));

    return Array.from(new Uint8Array(signature))
        .map((byte) => byte.toString(16).padStart(2, "0"))
        .join("");
}

function randomString(length: number) {
    const characters = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    let result = "";

    for (let index = 0; index < length; index += 1) {
        result += characters[Math.floor(Math.random() * characters.length)];
    }

    return result;
}

async function createAuth(shopUrl: string) {
    const params = {
        nonce: randomString(6),
        s2t: Math.floor(Date.now() / 1000).toString(),
        shop_url: shopUrl,
    };
    const dataString = Object.keys(params)
        .sort()
        .map((key) => `${key}=${params[key as keyof typeof params]}`)
        .join("&");
    const sign = await hmacSha256(`${dataString}&key=${SIGN_KEY}`, SIGN_KEY);

    return {
        nonce: params.nonce,
        s2t: params.s2t,
        sign,
    };
}

export async function createQueryAuth(shopUrl: string) {
    const auth = await createAuth(shopUrl);

    return `&s2t=${auth.s2t}&nonce=${auth.nonce}&sign=${encodeURIComponent(auth.sign)}`;
}

export async function createBodyAuth(shopUrl: string) {
    const auth = await createAuth(shopUrl);

    return {
        nonce: auth.nonce,
        s2t: Number(auth.s2t),
        sign: auth.sign,
    };
}
