import {
  shippingProtection,
} from "@captain/shipping-protection-sdk";
import type {
  InitParams,
  SdkCartData,
  ShippingProtectionInfo,
  UseShippingProtectionParams,
  UseShippingProtectionResult,
} from "./types.js";
import * as React from "react";

export function useShippingProtection({
  initParams,
}: UseShippingProtectionParams): UseShippingProtectionResult {
  const { init, initOver } = useShippingProtectionInit(initParams);
  const { getInfo } = useShippingProtectionActions();

  return {
    getInfo,
    init,
    initOver,
    sdk: shippingProtection,
    setting: shippingProtection.setting,
  };
}

function useShippingProtectionInit(initParams: InitParams) {
  const [initOver, setInitOver] = React.useState(false);

  React.useEffect(() => {
    setInitOver(false);
  }, [
    initParams.shop,
    initParams.country,
    initParams.locale,
    initParams.currency,
  ]);

  const init = React.useMemo(
    () => async () => {
      setInitOver(false);
      await shippingProtection.init({
        shop: initParams.shop,
        country: initParams.country,
        locale: initParams.locale,
        currency: initParams.currency,
      });
      setInitOver(true);
    },
    [
      initParams.shop,
      initParams.country,
      initParams.locale,
      initParams.currency,
    ],
  );

  return {
    init,
    initOver,
  };
}

function useShippingProtectionActions() {
  const getInfo = React.useMemo(
    () => (cartData: SdkCartData): Promise<ShippingProtectionInfo> => (
      shippingProtection.getInfo({ cartData })
    ),
    [],
  );

  return {
    getInfo,
  };
}
