import * as React from "react";
import type { SdkCartSetting, ShippingProtectionWidgetProps } from "./types.js";
import { classNames, formatPrice } from "./utils.js";
import "./styles.css";

export function ShippingProtectionWidget({
  checked,
  className,
  currency,
  disabled = false,
  info,
  onToggle,
  setting,
}: ShippingProtectionWidgetProps): React.ReactElement {
  const text = getWidgetContent(setting, checked);
  const showIcon =
    setting?.customized_style?.icon_visibility === 1 &&
    !!setting.tm_insurance_icon;
  const showPolicy =
    setting?.tm_is_claims_guide_url !== false && !!text.claimsGuideUrlText;
  const useSwitch = setting?.customized_style?.select_button !== 0;
  const handleToggle = (nextChecked: boolean) => {
    if (disabled) {
      return;
    }

    onToggle?.(nextChecked, info);
  };

  return (
    <div
      className={classNames("csp-widget", className)}
      style={getWidgetVariables(setting, checked)}
    >
      {showIcon ? (
        <div
          className={classNames(
            "csp-widget__icon",
            !checked && "csp-widget__icon--disabled",
          )}
        >
          <img src={setting.tm_insurance_icon} alt="" aria-hidden="true" />
        </div>
      ) : null}

      <div className="csp-widget__content">
        <div className="csp-widget__main">
          <div className="csp-widget__heading">
            <span className="csp-widget__title">{text.title}</span>
            <span className="csp-widget__price">
              ({formatPrice(info, currency)})
            </span>
          </div>

          {useSwitch ? (
            <button
              aria-checked={checked}
              aria-label="Shipping protection switch"
              className={classNames(
                "csp-widget__switch",
                checked && "csp-widget__switch--checked",
              )}
              disabled={disabled}
              role="switch"
              type="button"
              onClick={() => handleToggle(!checked)}
            >
              <span className="csp-widget__switch-knob" />
            </button>
          ) : (
            <label
              className={classNames(
                "csp-widget__checkbox",
                disabled && "csp-widget__checkbox--disabled",
              )}
            >
              <input
                checked={checked}
                disabled={disabled}
                type="checkbox"
                aria-label="Shipping protection checkbox"
                onChange={(event: { currentTarget: { checked: boolean } }) => {
                  handleToggle(event.currentTarget.checked);
                }}
              />
              <span className="csp-widget__checkbox-box" />
            </label>
          )}
        </div>

        <div className="csp-widget__description">{text.description}</div>

        {showPolicy ? (
          <div className="csp-widget__policy">
            {text.claimsGuideUrl ? (
              <a
                href={text.claimsGuideUrl}
                target="_blank"
                rel="noopener noreferrer"
              >
                {text.claimsGuideUrlText}
              </a>
            ) : (
              text.claimsGuideUrlText
            )}
          </div>
        ) : null}
      </div>
    </div>
  );
}

function getWidgetContent(setting: SdkCartSetting | null, checked: boolean) {
  const contentData = setting?.translation?.content_data;

  return {
    claimsGuideUrl: contentData?.claims_guide_url ?? setting?.tm_claims_guide_url ?? "",
    claimsGuideUrlText: contentData?.claims_guide_url_text ?? setting?.tm_claims_guide_url_text ?? "",
    description: checked
      ? contentData?.description ?? setting?.tm_description ?? ""
      : contentData?.disabled_description ?? setting?.tm_disabled_description ?? "",
    title: contentData?.title ?? setting?.tm_title ?? "",
  };
}

function getWidgetVariables(setting: SdkCartSetting | null, checked: boolean): Record<string, string> {
  const customized = setting?.customized_style;
  const variables: Record<string, string> = {};

  setColorVariable(variables, "--csp-widget-background", customized?.background);
  setColorVariable(variables, "--csp-widget-border-color", customized?.border_color);
  setPxVariable(variables, "--csp-widget-border-radius", customized?.widget_corner_radius);
  setPxVariable(variables, "--csp-widget-border-width", customized?.widget_border_size);
  setPxVariable(variables, "--csp-widget-padding-x", customized?.widget_horizontal_padding);
  setPxVariable(variables, "--csp-widget-padding-y", customized?.widget_vertical_padding);
  setColorVariable(variables, "--csp-title-color", customized?.title);
  setColorVariable(
    variables,
    "--csp-description-color",
    checked ? customized?.enable_description : customized?.disable_description,
  );
  setPxVariable(variables, "--csp-icon-size", customized?.icon_size);
  setPxVariable(variables, "--csp-icon-radius", customized?.icon_corner_radius);
  setColorVariable(variables, "--csp-switch-on-color", customized?.opt_in_action_button ?? setting?.tm_switch_color);
  setColorVariable(variables, "--csp-switch-off-color", customized?.opt_out_action_button);

  return variables;
}

function setColorVariable(
  variables: Record<string, string>,
  name: string,
  value: string | undefined,
) {
  if (value) {
    variables[name] = `#${value}`;
  }
}

function setPxVariable(
  variables: Record<string, string>,
  name: string,
  value: number | undefined,
) {
  if (value && value > 0) {
    variables[name] = `${value}px`;
  }
}
