import * as React from "react";
import { ShippingProtectionWidget } from "./ShippingProtectionWidget.js";
import { useShippingProtection } from "./useShippingProtection.js";
import type {
  InitParams,
  SdkCartSetting,
  ShippingProtectionInfo,
  ShippingProtectionProps,
} from "./types.js";

export function ShippingProtection(
  props: ShippingProtectionProps,
): React.ReactElement | null {
  const { className, onToggle } = props;
  const [checked, setChecked] = React.useState(false);
  const [togglePending, setTogglePending] = React.useState(false);
  const [error, setError] = React.useState<unknown>(null);
  const [info, setInfo] = React.useState<ShippingProtectionInfo | null>(null);
  const checkedRef = React.useMemo(() => ({ current: checked }), []);
  const onToggleRef = React.useMemo(() => ({ current: onToggle }), []);
  checkedRef.current = checked;
  onToggleRef.current = onToggle;
  const initParams: InitParams = {
    shop: props.shop,
    country: props.country,
    locale: props.locale,
    currency: props.currency,
  };
  const protection = useShippingProtection({
    checked,
    initParams,
  });

  const updateChecked = React.useMemo(
    () => async (nextChecked: boolean, nextInfo: ShippingProtectionInfo) => {
      const previousChecked = checkedRef.current;

      setTogglePending(true);
      setChecked(nextChecked);

      try {
        await onToggleRef.current?.(nextChecked, nextInfo);
      } catch {
        setChecked(previousChecked);
      } finally {
        setTogglePending(false);
      }
    },
    [],
  );

  React.useEffect(() => {
    let cancelled = false;

    protection
      .init()
      .then(() => {
        if (!cancelled) {
          setError(null);
        }
      })
      .catch((nextError: unknown) => {
        if (cancelled) return;
        setInfo(null);
        setError(nextError);
      });

    return () => {
      cancelled = true;
    };
  }, [protection.init]);

  React.useEffect(() => {
    if (!protection.initOver) {
      return;
    }

    let cancelled = false;

    protection
      .getInfo(props.cart)
      .then((nextInfo) => {
        if (cancelled) return;
        setInfo(nextInfo);
        setError(null);

        const shouldCheck = nextInfo.includedProtection || isDefaultChecked(protection.sdk.setting);

        if (nextInfo.isExcluded) {
          if (checkedRef.current || nextInfo.includedProtection) {
            void updateChecked(false, nextInfo);
          } else {
            setChecked(false);
          }
          return;
        }

        if (shouldCheck && !nextInfo.includedProtection && !checkedRef.current) {
          void updateChecked(true, nextInfo);
          return;
        }

        setChecked(shouldCheck);
      })
      .catch((nextError: unknown) => {
        if (cancelled) return;
        setInfo(null);
        setError(nextError);
      });

    return () => {
      cancelled = true;
    };
  }, [protection.getInfo, protection.initOver, props.cart, updateChecked]);

  if (error || !info || info.isExcluded) {
    return null;
  }

  return (
    <ShippingProtectionWidget
      checked={checked}
      className={className}
      currency={props.cart.currency}
      disabled={togglePending}
      info={info}
      setting={protection.setting}
      onToggle={(nextChecked, info) => {
        if (!togglePending) {
          void updateChecked(nextChecked, info);
        }
      }}
    />
  );
}

function isDefaultChecked(setting: SdkCartSetting | null) {
  return setting?.tm_default_display_status === 1;
}
