import { buildContext, fetchCartSetting, fetchCheckDisplay } from "./api.js";
import { resolveInfo } from "./core.js";
import type {
    GetInfoParams,
    InitParams,
    SdkCartSetting,
    SdkContext,
    ShippingProtectionInfo,
} from "./types.js";

class ShippingProtection {
    setting: SdkCartSetting | null = null;
    private context: SdkContext | null = null;

    async init(params: InitParams): Promise<void> {
        this.context = buildContext(params);
        this.setting = await fetchCartSetting(this.context);
    }

    async getInfo(params: GetInfoParams): Promise<ShippingProtectionInfo> {
        if (!this.setting || !this.context) {
            throw new Error("ShippingProtection SDK has not been initialized. Call init() before getInfo().");
        }

        let checkDisplay = undefined;

        if (this.setting.exclusion_has_value && this.setting.exclusion_type === 3) {
            try {
                checkDisplay = await fetchCheckDisplay(params.cartData, this.setting, this.context);
            } catch {
                checkDisplay = null;
            }
        }

        return resolveInfo(params.cartData, this.setting, checkDisplay);
    }

}

export const shippingProtection = new ShippingProtection();

export type {
    ExcludedReason,
    GetInfoParams,
    InitParams,
    SdkCartData,
    SdkCartDataItem,
    SdkCartSetting,
    ShippingProtectionInfo,
} from "./types.js";
