import type {
    ApiResult,
    CheckDisplayResult,
    InitParams,
    SdkCartData,
    SdkCartSetting,
    SdkContext,
} from "./types.js";
import { createBodyAuth, createQueryAuth } from "./signature.js";

const API_BASE_URL = "https://insurance.captaintop.com";

function appendOptional(params: URLSearchParams, key: string, value?: string) {
    if (value) {
        params.set(key, value);
    }
}

async function readJson<T>(response: Response): Promise<T> {
    if (!response.ok) {
        throw new Error(`ShippingProtection SDK request failed: ${response.status}`);
    }

    return response.json() as Promise<T>;
}

export function buildContext(params: InitParams): SdkContext {
    return {
        shop: params.shop,
        country: params.country,
        locale: params.locale,
        currency: params.currency,
        apiBaseUrl: API_BASE_URL,
    };
}

export async function fetchCartSetting(context: SdkContext): Promise<SdkCartSetting> {
    const params = new URLSearchParams({ shop_url: context.shop });
    appendOptional(params, "country", context.country);
    appendOptional(params, "locale", context.locale);
    appendOptional(params, "currency", context.currency);
    const signature = await createQueryAuth(context.shop);

    const result = await readJson<ApiResult<SdkCartSetting>>(
        await fetch(`${context.apiBaseUrl}/api/v1/getCartSettingByShopUrl?${params.toString()}${signature}`, {
            headers: { "content-type": "application/json" },
            method: "get",
        }),
    );

    if (result.code !== 200 || !result.data) {
        throw new Error("ShippingProtection SDK failed to load cart setting");
    }

    return result.data;
}

export async function fetchCheckDisplay(
    cart: SdkCartData,
    setting: SdkCartSetting,
    context: SdkContext,
): Promise<CheckDisplayResult | null> {
    const line_items = cart.items
        .filter((item) => String(item.product_id) !== String(setting.tm_product_exclusion))
        .map((item) => ({
            product_id: item.product_id,
            variant_id: item.variant_id,
            title: item.title ?? item.product_title ?? "",
            sku: String(item.sku ?? ""),
        }));

    return readJson<CheckDisplayResult>(
        await fetch(`${context.apiBaseUrl}/api/v1/checkDisplay`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
                shop_url: context.shop,
                line_items,
                country: context.country,
                locale: context.locale,
                ...await createBodyAuth(context.shop),
            }),
        }),
    );
}
