import type { CheckDisplayResult, ExcludedReason, SdkCartData, SdkCartSetting, ShippingProtectionInfo } from "./types.js";

interface Quote {
    price: string;
    variantId: string;
}

function parseVariants(raw: string | Record<string, string | number>) {
    if (typeof raw !== "string") {
        return raw;
    }

    try {
        const parsed = JSON.parse(raw) as Record<string, string | number>;
        return parsed && typeof parsed === "object" ? parsed : {};
    } catch {
        return {};
    }
}

export function findVariant(cartTotal: number, setting: SdkCartSetting): Quote {
    if (setting.tm_compute === 1) {
        const protectionPercentage = Number(setting.tm_proportion);
        const protectionPrice = cartTotal * (protectionPercentage / 100);
        const minPrice = Number(setting.tm_min_protection_val);
        const maxPrice = Number(setting.tm_max_protection_val);

        if (protectionPrice < minPrice) {
            return {
                price: String(setting.tm_min_protection_val),
                variantId: String(setting.tm_min_variant_id),
            };
        }

        if (protectionPrice > maxPrice) {
            return {
                price: String(setting.tm_max_protection_val),
                variantId: String(setting.tm_max_variant_id),
            };
        }

        const variants = parseVariants(setting.tm_variants);
        const matchedPrice = Object.keys(variants)
            .map(Number)
            .filter(Number.isFinite)
            .sort((a, b) => a - b)
            .find((price) => price >= protectionPrice);

        if (matchedPrice != null) {
            return {
                price: String(matchedPrice),
                variantId: String(variants[String(matchedPrice)]),
            };
        }
    } else {
        const fixedData = setting.tm_fixed_ladder
            .filter((item) => Number(item.min_value) <= cartTotal && cartTotal <= Number(item.max_value))
            .sort((a, b) => Number(b.insurance_price) - Number(a.insurance_price))[0];

        if (fixedData) {
            return {
                price: String(fixedData.insurance_price),
                variantId: String(fixedData.variant_id),
            };
        }
    }

    return {
        price: String(setting.tm_fixed_val),
        variantId: String(setting.tm_fixed_variant_id),
    };
}

function checkContainBlock(id: string, data: Array<string | number>) {
    return new Set(data.map(String)).has(id);
}

function localCheckDisplay(cart: SdkCartData, setting: SdkCartSetting): CheckDisplayResult {
    if (!setting.exclusion_has_value) {
        return { code: 200, data: { show: true, excluded_product_ids: [] } };
    }

    if (setting.exclusion_type === 1 || setting.exclusion_type === 2) {
        const excluded = cart.items
            .filter((item) => String(item.product_id) !== String(setting.tm_product_exclusion))
            .filter((item) => checkContainBlock(String(item.variant_id), setting.exclusion_variants))
            .map((item) => String(item.product_id));

        return {
            code: 200,
            data: {
                show: !(setting.excluded_hide_widget_show === 1 && excluded.length > 0),
                excluded_product_ids: excluded,
            },
        };
    }

    return { code: 200, data: { show: true, excluded_product_ids: [] } };
}

function resolveCheckDisplayData(checkDisplay?: CheckDisplayResult | null) {
    if (checkDisplay?.code === 200 && checkDisplay.data != null) {
        return {
            show: !!checkDisplay.data.show,
            reason: checkDisplay.data.reason,
            excludedProductIds: Array.isArray(checkDisplay.data.excluded_product_ids)
                ? checkDisplay.data.excluded_product_ids.map(String)
                : [],
        };
    }

    return {
        show: true,
        reason: undefined,
        excludedProductIds: [],
    };
}

export function resolveInfo(
    cart: SdkCartData,
    setting: SdkCartSetting,
    checkDisplay: CheckDisplayResult | null = localCheckDisplay(cart, setting),
): ShippingProtectionInfo {
    const hasInsuranceLine = cart.items.some(
        (item) => String(item.product_id) === String(setting.tm_product_exclusion),
    );
    const createInfo = (
        quote: Quote,
        isExcluded: boolean,
        excludedReason?: ExcludedReason,
    ): ShippingProtectionInfo => ({
        productId: setting.tm_product_exclusion,
        variantsId: quote.variantId,
        price: quote.price,
        includedProtection: hasInsuranceLine,
        isExcluded,
        ...(excludedReason ? { excludedReason } : {}),
    });

    const fallbackQuote = {
        price: setting.tm_fixed_val,
        variantId: setting.tm_fixed_variant_id,
    };

    if (!cart.items.length) {
        return createInfo(fallbackQuote, true, "empty_cart");
    }

    if (cart.items.some((item) => !item.product_id)) {
        return createInfo(fallbackQuote, true, "invalid_cart");
    }

    const hasNonInsuranceProduct = cart.items.some(
        (item) => String(item.product_id) !== String(setting.tm_product_exclusion),
    );

    if (!hasNonInsuranceProduct) {
        return createInfo(fallbackQuote, true, "only_shipping_protection");
    }

    const captainProductList = cart.items.find(
        (item) => String(item.product_id) === String(setting.tm_product_exclusion),
    );
    const checkDisplayData = resolveCheckDisplayData(checkDisplay);
    const excludedCheckDisplayProductIdSet = new Set(checkDisplayData.excludedProductIds);
    const isCheckDisplayExcludedProduct = (productId: number | string) =>
        excludedCheckDisplayProductIdSet.has(String(productId));

    const totalPrice = () => {
        let total = Number(cart.total_price);

        if (captainProductList) {
            total -= Number(captainProductList.final_line_price ?? 0);
        }

        if (setting.excluded_hide_widget_show === 2) {
            return cart.items
                .filter((item) => (
                    String(item.product_id) !== String(setting.tm_product_exclusion)
                    && !checkContainBlock(String(item.variant_id), setting.exclusion_variants)
                    && !isCheckDisplayExcludedProduct(item.product_id)
                ))
                .reduce((acc, item) => acc + Number(item.final_line_price ?? 0), 0);
        }

        for (const item of cart.items) {
            if (isCheckDisplayExcludedProduct(item.product_id)) {
                total -= Number(item.final_line_price ?? 0);
            }
        }

        return total;
    };

    const { price, variantId } = findVariant(totalPrice() / 100, setting);
    const isExcludedVariantLine = cart.items.some((item) => (
        checkContainBlock(String(item.variant_id), setting.exclusion_variants)
        || (hasInsuranceLine && cart.items.length === 1)
    ));
    const isHiddenByExclusion = () => {
        if (setting.excluded_hide_widget_show === 2) {
            const hasNotExcludedLine = cart.items.some((item) => (
                !checkContainBlock(String(item.variant_id), setting.exclusion_variants)
                || (hasInsuranceLine && cart.items.length === 1)
            ));

            return !hasNotExcludedLine && isExcludedVariantLine;
        }

        return isExcludedVariantLine;
    };
    const isLocalExcluded = isHiddenByExclusion();
    const isCheckDisplayExcluded = !checkDisplayData.show;
    const excludedReason = (() => {
        if (isCheckDisplayExcluded) {
            return checkDisplayData.reason || "check_display_hidden";
        }

        if (isLocalExcluded) {
            return "excluded_variant";
        }

        return undefined;
    })();

    return createInfo({ price, variantId }, isLocalExcluded || isCheckDisplayExcluded, excludedReason);
}
